INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'fill', 3, '{"stem": "填空(6)：王老师从图书馆拿了248本书平均分给7个班级，分完后有剩余。她最少要再从图书馆拿来（ ）本继续分，才能确保每个班分到的书一样多。"}', '4', '248÷7=35...3，再拿4本→7本→每班36本', 'jsj3_sx_v107', '["jsj3_sx","U4","p057","fill_06"]', 1, NULL);
