INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 2, '{"stem": "应用(1)：9枝玫瑰花包装成1束，457枝能包装成几束？还需几枝可以再包装成一束？（6分）"}', '50束, 还需2枝', '457÷9=50...7, 还需9-7=2枝', 'jsj3_sx_v107', '["jsj3_sx","U4","p059","apply_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 2, '{"stem": "应用(2)：一辆面包车限座8人，现在有182人要乘坐，至少需要多少辆面包车？（不含司机）（6分）"}', '23（辆）', '182÷8=22...6, 22+1=23（辆）（进一法）', 'jsj3_sx_v107', '["jsj3_sx","U4","p059","apply_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 2, '{"stem": "应用(3)：欢欢看一本书，计划每天看45页，8天看完。如果要在6天内看完，每天要看多少页？（6分）"}', '60（页）', '45×8=360, 360÷6=60（页）', 'jsj3_sx_v107', '["jsj3_sx","U4","p059","apply_03"]', 1, NULL);
