INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 3, '{"stem": "应用(5)：某品牌的婴儿奶粉单桶价格为198元，6桶一箱，整箱购买价格为960元。(1)如果选择整箱购买，平均每桶奶粉需要支付多少钱？(2)李阿姨只想购买一桶，她有100元、50元、20元、10元、5元、1元人民币若干张，在不需要找钱的情况下，怎么付款用的纸币张数最少？（8分）"}', '(1) 160元 (2) 1张100元+1张50元+2张20元+1张5元+3张1元', '(1) 960÷6=160（元）; (2) 198=100+50+20×2+5+1×3，共8张', 'jsj3_sx_v107', '["jsj3_sx","U4","p059","apply_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 3, '{"stem": "思维拓展：一个三位数除以8，所得的商是两位数，商的十位、个位上的数字与余数都相同。请写出所有满足条件的三位数。（10分）"}', '178, 267, 356, 445, 534, 623', '设商的十位、个位数字和余数都是a(a<8)，商=11a，被除数=11a×8+a=89a。a=2→178, a=3→267, a=4→356, a=5→445, a=6→534, a=7→623', 'jsj3_sx_v107', '["jsj3_sx","U4","p059","think_01"]', 1, NULL);